//! `bsc session mode` — switch a whole project between a completely LOCAL and a completely CLAUDE CLI
//! environment, and report which one it is in.
//!
//! # The mechanism already existed and nothing wrote it
//!
//! [`crate::session`] resolves `.claude/session.json` per level — machine, then hub, then worktree —
//! merged PER FIELD with the environment on top, and it already carries exactly what an environment
//! is: `provider`, `model`, `baseUrl`, `numCtx`. What it had was `resolve`, `get` and `describe`, and
//! no verb anywhere that wrote one. So a project's environment was something you could READ and
//! could only change by editing JSON by hand.
//!
//! This writes the HUB level and nothing else. Everything below inherits by the merge rule that was
//! already there, and a worktree that pinned its own provider still wins — which is the correct
//! behaviour for a per-field chain and the reason this is not a global setting.
//!
//! # Both configurations are DATA
//!
//! `console/model-defaults.json` already carries both halves: `anthropicModel` on one side,
//! `localModel` / `localBaseUrl` / `localNumCtx` on the other. Neither is restated here, so tuning a
//! mode is a data edit rather than a rebuild — and `numCtx` is the field most likely to need it,
//! because a local model is markedly more verbose and has to split its context far harder than Claude
//! does. The size it gets is a per-machine fact, not a constant.
//!
//! # Switching CLEARS rather than overwrites
//!
//! Going to `claude` removes `baseUrl` and `numCtx` instead of leaving them behind. A half-switched
//! project — Claude's model pointed at a localhost base URL — is the exact failure this verb exists to
//! prevent, and it is the shape a hand-edited file lands in most often.

pub use is_mode::is_mode;
pub use mode_defaults::mode_defaults;
pub use doc_for::doc_for;
pub use mode_of::mode_of;
pub use hub_session_path::hub_session_path;

use crate::session::{Resolved, SessionDoc, SESSION_DIR, SESSION_FILE};
use std::path::{Path, PathBuf};

/// The two environments this app ships. Deliberately closed: a third would be a third product.
pub const MODES: &[&str] = &["local", "claude"];

/// The packaged defaults both modes are built from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModeDefaults {
    pub anthropic_model: String,
    pub local_model: String,
    pub local_base_url: String,
    pub local_num_ctx: u64,
}

/// Merge one mode over whatever the hub file already holds, and write it back.
///
/// # It edits the JSON, it does not re-serialize the struct
///
/// The obvious implementation — parse to [`SessionDoc`], set four fields, `to_string_pretty` — is
/// WRONG in a way a struct-level test cannot see, and it broke here: `SessionDoc` writes every
/// `None` as an explicit `null`, and an explicit null is now a CLEAR. Re-serializing therefore
/// cleared `role`, `stream`, `writeScope` and everything else the hub was silent about, turning a
/// four-field switch into a whole-file override — the exact shape the chain's own doc rejects.
///
/// Editing the object also means a field a FUTURE version adds survives a mode switch made by an
/// older binary, which re-serializing through a struct can never promise.
///
/// Only the four environment fields move. `claude` writes an explicit null for the two that are
/// local-only, because silence would let a machine-level `baseUrl` keep applying and leave a Claude
/// model pointed at a local server.
pub fn write_hub_mode(hub: &Path, mode: &str, d: &ModeDefaults) -> Result<PathBuf, String> {
    let next = doc_for(mode, d)?;
    let path = hub_session_path(hub);
    let mut obj = match std::fs::read_to_string(&path) {
        Ok(raw) => match serde_json::from_str::<serde_json::Value>(&raw) {
            Ok(serde_json::Value::Object(m)) => m,
            Ok(_) => return Err(format!("{} is not a JSON object — refusing to overwrite it", path.display())),
            Err(e) => {
                return Err(format!(
                    "{} is not valid session JSON: {e} — refusing to overwrite it",
                    path.display()
                ))
            }
        },
        Err(_) => serde_json::Map::new(),
    };
    obj.entry("version").or_insert(serde_json::json!(1));
    obj.insert("provider".into(), serde_json::json!(next.provider));
    obj.insert("model".into(), serde_json::json!(next.model));
    // `json!(None::<T>)` is `null`, which is precisely the clear — so both modes write these two and
    // the difference is only what they write.
    obj.insert("baseUrl".into(), serde_json::json!(next.base_url));
    obj.insert("numCtx".into(), serde_json::json!(next.num_ctx));
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    }
    let body = serde_json::to_string_pretty(&serde_json::Value::Object(obj)).map_err(|e| e.to_string())?;
    std::fs::write(&path, format!("{body}\n")).map_err(|e| format!("cannot write {}: {e}", path.display()))?;
    Ok(path)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn defaults() -> ModeDefaults {
        ModeDefaults {
            anthropic_model: "claude-sonnet-4-6".into(),
            local_model: "qwen3-coder".into(),
            local_base_url: "http://localhost:11434/v1".into(),
            local_num_ctx: 65536,
        }
    }

    fn tmp(tag: &str) -> std::path::PathBuf {
        // NOT `std::env::temp_dir()`. A sibling module's tests build fixtures there and the resolver
        // walks UP from them, so with `TMPDIR` anywhere under $HOME the walk reaches the developer's
        // real `~/.claude/session.json` and merges it in — three of those tests fail exactly that way
        // (`session-config-tests-are-isolated-only-while-tmpdir-is-outside-home`). These fixtures do
        // not walk, but they are built inside a directory this test owns for the same reason.
        let p = std::env::temp_dir().join(format!("bsc-session-mode-{}-{tag}", std::process::id()));
        let _ = std::fs::remove_dir_all(&p);
        std::fs::create_dir_all(&p).unwrap();
        p
    }

    /// SWITCHING TO CLAUDE CLEARS. A Claude model pointed at a localhost base URL is the
    /// half-switched state this verb exists to prevent, and it is the shape a hand-edited file lands
    /// in most often — you change the model and forget the two fields that only meant anything to the
    /// other mode.
    #[test]
    fn switching_to_claude_clears_the_local_only_fields() {
        let d = defaults();
        let local = doc_for("local", &d).unwrap();
        assert_eq!(local.base_url.as_deref(), Some("http://localhost:11434/v1"));
        assert_eq!(local.num_ctx, Some(65536));
        let claude = doc_for("claude", &d).unwrap();
        assert_eq!(claude.provider.as_deref(), Some("anthropic"));
        assert!(claude.base_url.is_none(), "a claude session has no local base URL");
        assert!(claude.num_ctx.is_none(), "nor a local context size");
    }

    /// The toggle must not be LOSSY: two switches return the machine to where it started, byte for
    /// byte. Anything else means a project accumulates drift every time someone flips it.
    #[test]
    fn the_round_trip_is_byte_identical() {
        let d = defaults();
        let hub = tmp("round");
        let p = write_hub_mode(&hub, "local", &d).unwrap();
        let first = std::fs::read_to_string(&p).unwrap();
        write_hub_mode(&hub, "claude", &d).unwrap();
        write_hub_mode(&hub, "local", &d).unwrap();
        assert_eq!(std::fs::read_to_string(&p).unwrap(), first, "local -> claude -> local drifted");
    }

    /// A mode switch touches the FOUR environment fields and nothing else. The hub file is where a
    /// project's identity legitimately lives — its key, its plan store, its write scope — and a
    /// toggle that dropped them would quietly unconfigure the project it was asked to reconfigure.
    #[test]
    fn a_switch_preserves_every_field_that_is_not_the_environment() {
        let d = defaults();
        let hub = tmp("preserve");
        std::fs::create_dir_all(hub.join(SESSION_DIR)).unwrap();
        std::fs::write(
            hub_session_path(&hub),
            r#"{"projectKey":"studio-code","planDb":"/p/studio-code.db","role":"worker","writeScope":["src/**"],"provider":"anthropic"}"#,
        )
        .unwrap();
        write_hub_mode(&hub, "local", &d).unwrap();
        let doc: SessionDoc = serde_json::from_str(&std::fs::read_to_string(hub_session_path(&hub)).unwrap()).unwrap();
        assert_eq!(doc.project_key.as_deref(), Some("studio-code"), "the project key survived");
        assert_eq!(doc.plan_db.as_deref(), Some("/p/studio-code.db"));
        assert_eq!(doc.role.as_deref(), Some("worker"));
        assert_eq!(doc.write_scope.as_deref(), Some(&["src/**".to_string()][..]));
        assert_eq!(doc.provider.as_deref(), Some("ollama"), "and the environment changed");
    }

    /// A malformed hub file is REFUSED, never overwritten. The file carries a project's identity, and
    /// a stray comma is not a reason to throw it away — the caller can fix one typo, and cannot undo
    /// a silent replace.
    #[test]
    fn a_malformed_hub_file_is_refused_rather_than_clobbered() {
        let d = defaults();
        let hub = tmp("malformed");
        std::fs::create_dir_all(hub.join(SESSION_DIR)).unwrap();
        let bad = r#"{"projectKey":"studio-code",}"#;
        std::fs::write(hub_session_path(&hub), bad).unwrap();
        let e = write_hub_mode(&hub, "local", &d).expect_err("refused");
        assert!(e.contains("refusing to overwrite"), "{e}");
        assert_eq!(std::fs::read_to_string(hub_session_path(&hub)).unwrap(), bad, "and it is untouched");
    }

    /// The mode is read from the PROVIDER alone. A machine with a different local model installed, or
    /// a project pinned to a Claude tier, is still unambiguously in one mode — and reporting it as
    /// "no mode" would be useless exactly where the answer matters.
    #[test]
    fn the_mode_is_read_from_the_provider_not_the_model() {
        let mut r = Resolved::default();
        r.values.insert("provider".into(), "ollama".into());
        r.values.insert("model".into(), "some-other-local:70b".into());
        assert_eq!(mode_of(&r), Some("local"));
        r.values.insert("provider".into(), "anthropic".into());
        r.values.insert("model".into(), "claude-opus-4-5".into());
        assert_eq!(mode_of(&r), Some("claude"));
        r.values.insert("provider".into(), "openai".into());
        assert_eq!(mode_of(&r), None, "a third provider is in neither mode, and says so");
    }

    /// THE CLEAR MUST SURVIVE THE MERGE, not merely be written. This is the case that was WRONG and
    /// that the earlier tests could not see: they asserted the DOC's fields, and the doc was correct —
    /// `baseUrl: None`. What was broken is that a per-field chain could only ADD, so a machine-level
    /// `baseUrl` kept applying and the project ended up as a Claude model pointed at localhost.
    ///
    /// MEASURED on the real machine before the fix: `bsc session mode claude` reported
    /// `baseUrl http://localhost:11434 from ~/.claude/session.json`.
    #[test]
    fn switching_to_claude_clears_a_machine_level_base_url_through_the_chain() {
        let d = defaults();
        let root = tmp("chain");
        let home = root.join("home");
        let hub = root.join("home").join(".base-studio-code").join("projects").join("demo");
        std::fs::create_dir_all(hub.join(SESSION_DIR)).unwrap();
        std::fs::create_dir_all(home.join(SESSION_DIR)).unwrap();
        // The machine says local, as a developer's real machine does.
        std::fs::write(
            home.join(SESSION_DIR).join(SESSION_FILE),
            r#"{"provider":"ollama","model":"qwen3-coder","baseUrl":"http://localhost:11434","numCtx":32768}"#,
        )
        .unwrap();
        write_hub_mode(&hub, "claude", &d).unwrap();
        let r = crate::session::resolve_with(&hub, Some(&home), |_| None);
        assert_eq!(r.get("provider"), Some("anthropic"), "the project's provider wins");
        assert_eq!(r.get("model"), Some("claude-sonnet-4-6"));
        assert_eq!(r.get("baseUrl"), None, "the machine's local base URL is CLEARED, not inherited");
        assert_eq!(r.get("numCtx"), None, "and so is its context size");
        // ...and switching back re-establishes both from the packaged defaults rather than leaving
        // the project reliant on whatever the machine happens to say.
        write_hub_mode(&hub, "local", &d).unwrap();
        let r2 = crate::session::resolve_with(&hub, Some(&home), |_| None);
        assert_eq!(r2.get("baseUrl"), Some("http://localhost:11434/v1"));
        assert_eq!(r2.get("numCtx"), Some("65536"));
    }

    /// SILENCE STILL INHERITS. The clear is an explicit null and must not have turned every absent
    /// field into one — that would make the chain a whole-file override, which is the shape its own
    /// doc rejects.
    #[test]
    fn a_field_a_level_is_silent_about_still_inherits() {
        let d = defaults();
        let root = tmp("silent");
        let home = root.join("home");
        let hub = root.join("home").join(".base-studio-code").join("projects").join("demo");
        std::fs::create_dir_all(hub.join(SESSION_DIR)).unwrap();
        std::fs::create_dir_all(home.join(SESSION_DIR)).unwrap();
        std::fs::write(
            home.join(SESSION_DIR).join(SESSION_FILE),
            r#"{"provider":"ollama","role":"worker","stream":"api"}"#,
        )
        .unwrap();
        write_hub_mode(&hub, "local", &d).unwrap();
        let r = crate::session::resolve_with(&hub, Some(&home), |_| None);
        assert_eq!(r.get("role"), Some("worker"), "the hub says nothing about role, so it inherits");
        assert_eq!(r.get("stream"), Some("api"));
        assert_eq!(r.get("provider"), Some("ollama"), "and the hub's own value applies");
    }

    #[test]
    fn an_unknown_mode_is_refused_naming_the_set() {
        let e = doc_for("hybrid", &defaults()).expect_err("not a mode");
        assert!(e.contains("local") && e.contains("claude"), "{e}");
        assert!(is_mode("local") && is_mode("claude") && !is_mode("hybrid"));
    }

    /// The packaged file really carries both halves — if it stops, every mode written from it is a
    /// guess, and this fails rather than letting one through.
    #[test]
    fn both_configurations_come_from_the_packaged_defaults() {
        let d = mode_defaults().expect("console/model-defaults.json resolves");
        assert!(d.anthropic_model.starts_with("claude"), "{}", d.anthropic_model);
        assert!(!d.local_model.is_empty());
        assert!(d.local_base_url.starts_with("http"), "{}", d.local_base_url);
        assert!(d.local_num_ctx >= 4096, "a context that small would split every turn");
    }
}
